const std=@import("std");
const regex=@import("regex");
pub fn main(init: std.process.Init) !void {
 const allocator=std.heap.page_allocator;
 const io=std.Io.Threaded.global_single_threaded.io();
 var args=try std.process.Args.Iterator.initAllocator(init.minimal.args,allocator);defer args.deinit();_ = args.next();const path=args.next().?;
 const source=try std.Io.Dir.cwd().readFileAlloc(io,path,allocator,.limited(1024*1024));defer allocator.free(source);
 var diagnostic:?regex.CompileErrorReason=null;
 var re=regex.Regex.compileWithFlagsDiagnostic(allocator,source,.{.ecmascript=true,.case_insensitive=true},&diagnostic) catch |err| {std.debug.print("ERR {s} {s}\n",.{@errorName(err),if(diagnostic)|d|@tagName(d) else "unknown"});return err;};defer re.deinit();std.debug.print("OK\n",.{});
}
